package main

import (
	"fmt"
	"sync"
)

func main() {
	var wg sync.WaitGroup
	var out [3]int
	for i := 0; i < 3; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			out[i] = i
		}()
	}
	wg.Wait()
	fmt.Println(out[0])
	fmt.Println(out[1])
	fmt.Println(out[2])
}

