package main

import (
	"fmt"
	"sync"
)

type box struct{ n int }

func (b *box) inc() {
	b.n++
}

func main() {
	b := &box{n: 3}
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		b.inc()
	}()
	wg.Wait()
	fmt.Println(b.n)
}

